---- MODULE W4Od1m4p2t1 ----
EXTENDS Integers, FiniteSets

Aircraft == {"a1", "a2", "a3"}
Runways  == {"r1", "r2"}
QCAP     == 2
NONE     == "none"

VARIABLES pending, transit, queue, runwayOf, landed
vars == <<pending, transit, queue, runwayOf, landed>>

OnRunway == { runwayOf[r] : r \in {rr \in Runways : runwayOf[rr] # NONE} }

Init ==
    /\ pending  = Aircraft
    /\ transit  = {}
    /\ queue    = {}
    /\ runwayOf = [r \in Runways |-> NONE]
    /\ landed   = {}

Depart(a) ==
    /\ a \in pending
    /\ pending' = pending \ {a}
    /\ transit' = transit \cup {a}
    /\ UNCHANGED <<queue, runwayOf, landed>>

Admit(a) ==
    /\ a \in transit
    /\ Cardinality(queue) < QCAP
    /\ transit' = transit \ {a}
    /\ queue'   = queue \cup {a}
    /\ UNCHANGED <<pending, runwayOf, landed>>

Assign(a, r) ==
    /\ a \in queue
    /\ runwayOf[r] = NONE
    /\ queue'    = queue \ {a}
    /\ runwayOf' = [runwayOf EXCEPT ![r] = a]
    /\ UNCHANGED <<pending, transit, landed>>

Land(r) ==
    /\ runwayOf[r] # NONE
    /\ landed'   = landed \cup {runwayOf[r]}
    /\ runwayOf' = [runwayOf EXCEPT ![r] = NONE]
    /\ UNCHANGED <<pending, transit, queue>>

Recycle(a) ==
    /\ a \in landed
    /\ landed'  = landed \ {a}
    /\ pending' = pending \cup {a}
    /\ UNCHANGED <<transit, queue, runwayOf>>

Next ==
    \/ \E a \in Aircraft : Depart(a)
    \/ \E a \in Aircraft : Recycle(a)
    \/ \E a \in Aircraft : Admit(a)
    \/ \E a \in Aircraft, r \in Runways : Assign(a, r)
    \/ \E r \in Runways : Land(r)

Spec == Init /\ [][Next]_vars

TypeOK ==
    /\ pending  \subseteq Aircraft
    /\ transit  \subseteq Aircraft
    /\ queue    \subseteq Aircraft
    /\ runwayOf \in [Runways -> Aircraft \cup {NONE}]
    /\ landed   \subseteq Aircraft

Conservation ==
    /\ (pending \cup transit \cup queue \cup OnRunway \cup landed) = Aircraft
    /\ pending \cap transit = {}
    /\ pending \cap queue = {}
    /\ pending \cap OnRunway = {}
    /\ pending \cap landed = {}
    /\ transit \cap queue = {}
    /\ transit \cap OnRunway = {}
    /\ transit \cap landed = {}
    /\ queue \cap OnRunway = {}
    /\ queue \cap landed = {}
    /\ OnRunway \cap landed = {}
====

---- MODULE W4Od10m4p5t1 ----
EXTENDS Integers, FiniteSets

Trains == {"t1", "t2", "t3"}
QCAP   == 2

VARIABLES pool, wire, queue, granted
vars == <<pool, wire, queue, granted>>

Init ==
    /\ pool    = Trains
    /\ wire    = {}
    /\ queue   = {}
    /\ granted = {}

Request(t) ==
    /\ t \in pool
    /\ pool' = pool \ {t}
    /\ wire' = wire \cup {t}
    /\ UNCHANGED <<queue, granted>>

Stage(t) ==
    /\ t \in wire
    /\ Cardinality(queue) < QCAP
    /\ wire'  = wire \ {t}
    /\ queue' = queue \cup {t}
    /\ UNCHANGED <<pool, granted>>

Grant(t) ==
    /\ t \in queue
    /\ queue'   = queue \ {t}
    /\ granted' = granted \cup {t}
    /\ UNCHANGED <<pool, wire>>

Cancel(t) ==
    /\ t \in queue
    /\ queue' = queue \ {t}
    /\ pool'  = pool \cup {t}
    /\ UNCHANGED <<wire, granted>>

Done ==
    /\ granted = Trains
    /\ UNCHANGED vars

Next ==
    \/ \E t \in Trains : Request(t)
    \/ \E t \in Trains : Stage(t)
    \/ \E t \in Trains : Grant(t)
    \/ \E t \in Trains : Cancel(t)
    \/ Done

Spec == Init /\ [][Next]_vars

TypeOK ==
    /\ pool    \subseteq Trains
    /\ wire    \subseteq Trains
    /\ queue   \subseteq Trains
    /\ granted \subseteq Trains

Partitioned ==
    /\ (pool \cup wire \cup queue \cup granted) = Trains
    /\ pool \cap wire = {}
    /\ pool \cap queue = {}
    /\ pool \cap granted = {}
    /\ wire \cap queue = {}
    /\ wire \cap granted = {}
    /\ queue \cap granted = {}
====
